import sys


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 20000))

    memo: dict[str, int | str] = {}
    visiting: set[str] = set()

    def tokenize(s: str) -> list[tuple[str, str | int]]:
        tokens: list[tuple[str, str | int]] = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(("NUM", int(s[i:j])))
                i = j
            elif ch.isalpha():
                j = i
                while j < n and s[j].isalnum():
                    j += 1
                word = s[i:j]
                if word in ("SUM", "MIN", "MAX", "IF"):
                    tokens.append(("FUNC", word))
                else:
                    tokens.append(("CELL", word))
                i = j
            elif i + 1 < n and s[i : i + 2] in ("<=", ">=", "<>"):
                tokens.append(("OP", s[i : i + 2]))
                i += 2
            else:
                tokens.append((ch, ch))
                i += 1
        return tokens

    def is_err(v: int | str) -> bool:
        return isinstance(v, str)

    def eval_cell(name: str) -> int | str:
        if name not in cells:
            return 0
        if name in memo:
            return memo[name]
        if name in visiting:
            return "#CYCLE!"

        visiting.add(name)
        content = cells[name]
        if not content.startswith("="):
            val: int | str = int(content)
        else:
            tokens = tokenize(content[1:])
            pos = 0

            def peek() -> tuple[str, str | int] | None:
                return tokens[pos] if pos < len(tokens) else None

            def consume() -> tuple[str, str | int]:
                nonlocal pos
                tok = tokens[pos]
                pos += 1
                return tok

            def skip_expr() -> None:
                nonlocal pos
                depth = 0
                while pos < len(tokens):
                    kind = tokens[pos][0]
                    if kind == "(":
                        depth += 1
                    elif kind == ")":
                        if depth == 0:
                            break
                        depth -= 1
                    elif kind == "," and depth == 0:
                        break
                    elif kind == "OP" and depth == 0:
                        break
                    elif kind == "=" and depth == 0:
                        break
                    pos += 1

            def parse_expr() -> int | str:
                left = parse_term()
                while True:
                    tok = peek()
                    if tok is not None and tok[0] in ("+", "-"):
                        op = consume()[0]
                        if is_err(left):
                            skip_expr()
                            return left
                        right = parse_term()
                        if is_err(right):
                            return right
                        left = left + right if op == "+" else left - right  # type: ignore[operator]
                    else:
                        break
                return left

            def parse_term() -> int | str:
                left = parse_unary()
                while True:
                    tok = peek()
                    if tok is not None and tok[0] in ("*", "/"):
                        op = consume()[0]
                        if is_err(left):
                            skip_expr()
                            return left
                        right = parse_unary()
                        if is_err(right):
                            return right
                        if op == "*":
                            left = left * right  # type: ignore[operator]
                        else:
                            if right == 0:
                                return "#DIV/0!"
                            q = abs(left) // abs(right)  # type: ignore[arg-type]
                            left = -q if (left < 0) ^ (right < 0) else q  # type: ignore[operator]
                    else:
                        break
                return left

            def parse_unary() -> int | str:
                tok = peek()
                if tok is not None and tok[0] == "-":
                    consume()
                    val_u = parse_unary()
                    if is_err(val_u):
                        return val_u
                    return -val_u  # type: ignore[operator]
                return parse_atom()

            def parse_atom() -> int | str:
                tok = consume()
                kind, val_t = tok
                if kind == "NUM":
                    return val_t  # type: ignore[return-value]
                if kind == "CELL":
                    return eval_cell(val_t)  # type: ignore[arg-type]
                if kind == "(":
                    res = parse_expr()
                    if peek() is not None and peek()[0] == ")":  # type: ignore[index]
                        consume()
                    return res
                # FUNC
                func_name = val_t
                consume()  # "("
                if func_name == "IF":
                    left = parse_expr()
                    op_tok = consume()
                    op = op_tok[1]
                    right = parse_expr()
                    consume()  # ","
                    if is_err(left):
                        skip_expr()  # then
                        consume()  # ","
                        skip_expr()  # else
                        consume()  # ")"
                        return left
                    if is_err(right):
                        skip_expr()  # then
                        consume()  # ","
                        skip_expr()  # else
                        consume()  # ")"
                        return right
                    cond = (
                        (left == right)
                        if op == "="
                        else (left != right)
                        if op == "<>"
                        else (left < right)  # type: ignore[operator]
                        if op == "<"
                        else (left <= right)  # type: ignore[operator]
                        if op == "<="
                        else (left > right)  # type: ignore[operator]
                        if op == ">"
                        else (left >= right)  # type: ignore[operator]
                    )
                    if cond:
                        res = parse_expr()
                        consume()  # ","
                        skip_expr()  # else
                        consume()  # ")"
                        return res
                    else:
                        skip_expr()  # then
                        consume()  # ","
                        res = parse_expr()
                        consume()  # ")"
                        return res

                # SUM, MIN, MAX
                vals: list[int] = []
                err: str | None = None
                while True:
                    if err is not None:
                        skip_expr()
                    elif (
                        pos + 1 < len(tokens)
                        and tokens[pos][0] == "CELL"
                        and tokens[pos + 1][0] == ":"
                    ):
                        c1 = str(consume()[1])
                        consume()  # ":"
                        c2 = str(consume()[1])
                        col1, row1 = c1[0], int(c1[1:])
                        col2, row2 = c2[0], int(c2[1:])
                        r_lo, r_hi = min(row1, row2), max(row1, row2)
                        c_lo, c_hi = min(col1, col2), max(col1, col2)
                        for r in range(r_lo, r_hi + 1):
                            for c_ord in range(ord(c_lo), ord(c_hi) + 1):
                                cname = f"{chr(c_ord)}{r}"
                                if cname in cells:
                                    v = eval_cell(cname)
                                    if is_err(v):
                                        err = v  # type: ignore[assignment]
                                        break
                                    vals.append(v)  # type: ignore[arg-type]
                            if err is not None:
                                break
                    else:
                        v = parse_expr()
                        if is_err(v):
                            err = v  # type: ignore[assignment]
                        else:
                            vals.append(v)  # type: ignore[arg-type]

                    if peek() is not None and peek()[0] == ",":  # type: ignore[index]
                        consume()
                    else:
                        consume()  # ")"
                        break

                if err is not None:
                    return err
                if not vals:
                    return 0
                if func_name == "SUM":
                    return sum(vals)
                if func_name == "MIN":
                    return min(vals)
                return max(vals)

            val = parse_expr()

        visiting.remove(name)
        memo[name] = val
        return val

    return {name: eval_cell(name) for name in cells}
